11	// RMSNorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch
12	// Format: Abs-style with platform_ascendc and EXEC_KERNEL_CMD
13	
14	#include <algorithm>
15	#include <cstdint>
16	
17	#include <torch/extension.h>
18	#include <torch/library.h>
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	
23	#include "aclrtlaunch_rms_norm_merge_n.h"
24	#include "aclrtlaunch_rms_norm_single_row.h"
25	#include "aclrtlaunch_rms_norm_splitd.h"
26	
27	// ---------------------------------------------------------------------------
28	// Tiling constants
29	// ---------------------------------------------------------------------------
30	
31	constexpr int32_t DEFAULT_BLOCK_M = 64;
32	constexpr int32_t DEFAULT_ROW_FACTOR = 8;
33	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
34	
35	// ---------------------------------------------------------------------------
36	// Host function
37	// ---------------------------------------------------------------------------
38	
39	namespace ascend_kernel {
40	
41	std::vector<at::Tensor> rms_norm(const at::Tensor &x, const at::Tensor &gamma, double eps)
42	{
43	    TORCH_CHECK(x.dim() == 2, "x must be [M, N]");
44	    TORCH_CHECK(gamma.dim() == 1, "gamma must be [N]");
45	    TORCH_CHECK(
46	        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
47	            x.scalar_type() == at::kBFloat16,
48	        "x must be float16, float32, or bfloat16");
49	    TORCH_CHECK(gamma.scalar_type() == x.scalar_type(),
50	        "gamma must have the same dtype as x");
51	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
52	    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
53	    TORCH_CHECK(static_cast<int32_t>(x.sizes()[1]) == static_cast<int32_t>(gamma.sizes()[0]),
54	        "gamma shape mismatch");
55	
56	    int32_t M = static_cast<int32_t>(x.sizes()[0]);
57	    int32_t N = static_cast<int32_t>(x.sizes()[1]);
58	
59	    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
60	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
61	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
62	
63	    at::Tensor y = at::empty_like(x);
64	    at::Tensor invRms = at::empty({M}, x.options());
65	
66	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
67	    int64_t dtypeFlag = 0;
68	    if (x.scalar_type() == at::kHalf) {
69	        dtypeFlag = 1;
70	    } else if (x.scalar_type() == at::kBFloat16) {
71	        dtypeFlag = 2;
72	    }
73	
74	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
75	    int32_t blockM = DEFAULT_BLOCK_M;
76	    int32_t rowFactor = DEFAULT_ROW_FACTOR;
77	    float epsVal = static_cast<float>(eps);
78	    float invN = 1.0f / static_cast<float>(N);
79	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
80	
81	    // Strategy dispatch: select kernel name and params
82	    if (N <= 1024) {
83	        EXEC_KERNEL_CMD(rms_norm_merge_n, blockDim,
84	                        x, gamma, y, invRms,
85	                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor, epsVal, invN,
86	                        dtypeFlag);
87	    } else if (N > 8192) {
88	        EXEC_KERNEL_CMD(rms_norm_splitd, blockDim,
89	                        x, gamma, y, invRms,
90	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
91	                        dtypeFlag);
92	    } else {
93	        EXEC_KERNEL_CMD(rms_norm_single_row, blockDim,
94	                        x, gamma, y, invRms,
95	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
96	                        dtypeFlag);
97	    }
98	
99	    return {y, invRms};
100	}
101	
102	}  // namespace ascend_kernel
