// AscendC AdvanceStep kernel — int64 per-sequence update with gather
// Computes: input_tokens', input_positions', seq_lens', slot_mapping'
// from 6 inputs + 3 scalars.  All tensors are int64.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t BLOCK_M = 8;           // sequences per logical block
constexpr int32_t PAD_STRIDE = 48;        // reference.total_core_num = 48
constexpr int32_t NUM_PHYSICAL_CORES = 20;

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> &dst,
    const AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}


class AdvanceStepKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR in_tokens, GM_ADDR in_sampled,
        GM_ADDR in_positions, GM_ADDR in_seqlens,
        GM_ADDR in_slots, GM_ADDR in_block_tables,
        GM_ADDR out_tokens, GM_ADDR out_positions,
        GM_ADDR out_seqlens, GM_ADDR out_slots,
        int64_t num_seqs, int64_t num_queries,
        int64_t block_size_val, int64_t max_blocks_per_seq,
        int64_t block_m, int64_t used_core_num, int64_t tasks_per_core)
    {
        numSeqs_ = num_seqs;
        numQueries_ = num_queries;
        blockSize_ = block_size_val;
        maxBlocksPerSeq_ = max_blocks_per_seq;
        blockM_ = block_m;
        usedCoreNum_ = used_core_num;
        tasksPerCore_ = tasks_per_core;

        // Global tensors — inputs
        inputTokensGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(in_tokens),
                                       static_cast<uint64_t>(num_seqs));
        sampledGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(in_sampled),
                                   static_cast<uint64_t>(num_queries));
        inputPositionsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(in_positions),
                                          static_cast<uint64_t>(num_seqs));
        seqLensGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(in_seqlens),
                                   static_cast<uint64_t>(num_seqs));
        slotMappingGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(in_slots),
                                       static_cast<uint64_t>(num_seqs));
        blockTablesGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(in_block_tables),
                                       static_cast<uint64_t>(num_seqs) * max_blocks_per_seq);

        // Global tensors — outputs
        outTokensGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(out_tokens),
                                     static_cast<uint64_t>(num_seqs));
        outPositionsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(out_positions),
                                        static_cast<uint64_t>(num_seqs));
        outSeqlensGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(out_seqlens),
                                      static_cast<uint64_t>(num_seqs));
        outSlotsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(out_slots),
                                    static_cast<uint64_t>(num_seqs));

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // TQue for input tiles (BLOCK_M int64 elements each)
        pipe_.InitBuffer(tokensInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
        pipe_.InitBuffer(sampledInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
        pipe_.InitBuffer(positionsInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
        pipe_.InitBuffer(seqlensInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
        pipe_.InitBuffer(slotsInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));

        // TBuf for block_tables flat (max_blocks_per_seq int64 elements)
        pipe_.InitBuffer(btFlatBuf_, static_cast<uint32_t>(maxBlocksPerSeq_ * sizeof(int64_t)));

        // TQue for output tiles
        pipe_.InitBuffer(tokensOutQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
        pipe_.InitBuffer(positionsOutQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
        pipe_.InitBuffer(seqlensOutQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
        pipe_.InitBuffer(slotsOutQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));

        // Scalar buffer for seq_lens_old (needed for input_positions and slot_mapping)
        pipe_.InitBuffer(seqlensOldBuf_, BLOCK_M * sizeof(int64_t));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();

            // Preload block_tables[0, :] flat into UB (used for gather by all sequences)
            btFlatLocal_ = btFlatBuf_.Get<int64_t>();
            LoadGmToUb(btFlatLocal_, blockTablesGM_, static_cast<uint32_t>(maxBlocksPerSeq_));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();

            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int bx = coreIdx * tasksPerCore_ + localIdx;
                int blockCount = CeilDivI32(static_cast<int32_t>(numSeqs_), BLOCK_M);
                if (bx >= blockCount) { continue; }

                int startSeq = bx * BLOCK_M;
                int curSeqs = static_cast<int32_t>(numSeqs_) - startSeq;
                if (curSeqs > BLOCK_M) { curSeqs = BLOCK_M; }

                ProcessBlock(startSeq, curSeqs);
            }
        }
    }

private:
    // ── CopyIn: load tiles from GM → UB ─────────────────────────────────
    __aicore__ inline void CopyInTokens(int64_t start, int32_t count)
    {
        tokensInLocal_ = tokensInQueue_.AllocTensor<int64_t>();
        LoadGmToUb(tokensInLocal_, inputTokensGM_[start], static_cast<uint32_t>(count));
        tokensInQueue_.EnQue(tokensInLocal_);
    }

    __aicore__ inline void CopyInSampled(int64_t start, int32_t count)
    {
        sampledInLocal_ = sampledInQueue_.AllocTensor<int64_t>();
        LoadGmToUb(sampledInLocal_, sampledGM_[start], static_cast<uint32_t>(count));
        sampledInQueue_.EnQue(sampledInLocal_);
    }

    __aicore__ inline void CopyInPositions(int64_t start, int32_t count)
    {
        positionsInLocal_ = positionsInQueue_.AllocTensor<int64_t>();
        LoadGmToUb(positionsInLocal_, inputPositionsGM_[start], static_cast<uint32_t>(count));
        positionsInQueue_.EnQue(positionsInLocal_);
    }

    __aicore__ inline void CopyInSeqlens(int64_t start, int32_t count)
    {
        seqlensInLocal_ = seqlensInQueue_.AllocTensor<int64_t>();
        LoadGmToUb(seqlensInLocal_, seqLensGM_[start], static_cast<uint32_t>(count));
        seqlensInQueue_.EnQue(seqlensInLocal_);
    }

    __aicore__ inline void CopyInSlots(int64_t start, int32_t count)
    {
        slotsInLocal_ = slotsInQueue_.AllocTensor<int64_t>();
        LoadGmToUb(slotsInLocal_, slotMappingGM_[start], static_cast<uint32_t>(count));
        slotsInQueue_.EnQue(slotsInLocal_);
    }

    // ── CopyOut: store tiles from UB → GM ───────────────────────────────
    __aicore__ inline void CopyOutTokens(int64_t start, int32_t count)
    {
        tokensOutLocal_ = tokensOutQueue_.DeQue<int64_t>();
        StoreUbToGm(outTokensGM_[start], tokensOutLocal_, static_cast<uint32_t>(count));
        tokensOutQueue_.FreeTensor(tokensOutLocal_);
    }

    __aicore__ inline void CopyOutPositions(int64_t start, int32_t count)
    {
        positionsOutLocal_ = positionsOutQueue_.DeQue<int64_t>();
        StoreUbToGm(outPositionsGM_[start], positionsOutLocal_, static_cast<uint32_t>(count));
        positionsOutQueue_.FreeTensor(positionsOutLocal_);
    }

    __aicore__ inline void CopyOutSeqlens(int64_t start, int32_t count)
    {
        seqlensOutLocal_ = seqlensOutQueue_.DeQue<int64_t>();
        StoreUbToGm(outSeqlensGM_[start], seqlensOutLocal_, static_cast<uint32_t>(count));
        seqlensOutQueue_.FreeTensor(seqlensOutLocal_);
    }

    __aicore__ inline void CopyOutSlots(int64_t start, int32_t count)
    {
        slotsOutLocal_ = slotsOutQueue_.DeQue<int64_t>();
        StoreUbToGm(outSlotsGM_[start], slotsOutLocal_, static_cast<uint32_t>(count));
        slotsOutQueue_.FreeTensor(slotsOutLocal_);
    }

    // ── Compute: per-sequence processing ───────────────────────────────
    __aicore__ inline void ComputeBlock(int64_t startSeq, int32_t curSeqs)
    {
        // Allocate output tensors
        tokensOutLocal_ = tokensOutQueue_.AllocTensor<int64_t>();
        positionsOutLocal_ = positionsOutQueue_.AllocTensor<int64_t>();
        seqlensOutLocal_ = seqlensOutQueue_.AllocTensor<int64_t>();
        slotsOutLocal_ = slotsOutQueue_.AllocTensor<int64_t>();
        seqlensOldLocal_ = seqlensOldBuf_.Get<int64_t>();

        // DeQue input tensors after copy-in
        tokensInLocal_ = tokensInQueue_.DeQue<int64_t>();
        sampledInLocal_ = sampledInQueue_.DeQue<int64_t>();
        positionsInLocal_ = positionsInQueue_.DeQue<int64_t>();
        seqlensInLocal_ = seqlensInQueue_.DeQue<int64_t>();
        slotsInLocal_ = slotsInQueue_.DeQue<int64_t>();

        // Save old seq_lens (needed for input_positions and slot_mapping)
        for (int i = 0; i < curSeqs; ++i) {
            seqlensOldLocal_.SetValue(i, seqlensInLocal_.GetValue(i));
        }

        // Per-sequence processing
        for (int i = 0; i < curSeqs; ++i) {
            int64_t seqId = startSeq + i;

            if (seqId < numQueries_) {
                // Phase A: Valid sequence

                // (a) Copy sampled token → input token
                int64_t tokenVal = sampledInLocal_.GetValue(i);
                tokensOutLocal_.SetValue(i, tokenVal);

                // (b) next_seq_len = old_seq_len + 1
                int64_t oldSeqLen = seqlensOldLocal_.GetValue(i);
                int64_t nextSeqLen = oldSeqLen + 1;
                seqlensOutLocal_.SetValue(i, nextSeqLen);

                // (c) input_position = old_seq_len (= next_input_pos)
                positionsOutLocal_.SetValue(i, oldSeqLen);

                // (d) slot_mapping computation
                //     next_input_pos = old_seq_len
                //     block_index = next_input_pos / block_size
                //     block_offset = next_input_pos % block_size
                int64_t nextInputPos = oldSeqLen;
                int64_t blockIndex = nextInputPos / blockSize_;
                int64_t blockOffset = nextInputPos - blockIndex * blockSize_;

                // (e) Gather from block_tables_flat[block_index]
                int64_t btVal = btFlatLocal_.GetValue(static_cast<int32_t>(blockIndex));

                // (f) slot_num = (btVal + max_blocks_per_seq * seqId) * block_size + block_offset
                int64_t slotNum = (btVal + maxBlocksPerSeq_ * seqId) * blockSize_ + blockOffset;
                slotsOutLocal_.SetValue(i, slotNum);

            } else {
                // Phase B: Pad sequence — stride-48 reset
                // Keep original values by default; only reset every 48th pad element
                tokensOutLocal_.SetValue(i, tokensInLocal_.GetValue(i));
                positionsOutLocal_.SetValue(i, positionsInLocal_.GetValue(i));
                seqlensOutLocal_.SetValue(i, seqlensInLocal_.GetValue(i));

                int64_t padIdx = seqId - numQueries_;
                // Check: (padIdx // PAD_STRIDE) * PAD_STRIDE == padIdx
                int64_t quotient = padIdx / PAD_STRIDE;
                int64_t check = quotient * PAD_STRIDE;
                if (check == padIdx) {
                    tokensOutLocal_.SetValue(i, 0);
                    positionsOutLocal_.SetValue(i, 0);
                    slotsOutLocal_.SetValue(i, -1);
                } else {
                    slotsOutLocal_.SetValue(i, slotsInLocal_.GetValue(i));
                }
            }
        }

        // Free input tensors
        tokensInQueue_.FreeTensor(tokensInLocal_);
        sampledInQueue_.FreeTensor(sampledInLocal_);
        positionsInQueue_.FreeTensor(positionsInLocal_);
        seqlensInQueue_.FreeTensor(seqlensInLocal_);
        slotsInQueue_.FreeTensor(slotsInLocal_);

        // EnQue output tensors
        tokensOutQueue_.EnQue(tokensOutLocal_);
        positionsOutQueue_.EnQue(positionsOutLocal_);
        seqlensOutQueue_.EnQue(seqlensOutLocal_);
        slotsOutQueue_.EnQue(slotsOutLocal_);
    }

    // ── ProcessBlock: CopyIn → Compute → CopyOut ────────────────────────
    __aicore__ inline void ProcessBlock(int64_t startSeq, int32_t curSeqs)
    {
        // CopyIn all 5 input tiles
        CopyInTokens(startSeq, curSeqs);
        CopyInSampled(startSeq, curSeqs);
        CopyInPositions(startSeq, curSeqs);
        CopyInSeqlens(startSeq, curSeqs);
        CopyInSlots(startSeq, curSeqs);

        // Compute
        ComputeBlock(startSeq, curSeqs);

        // CopyOut all 4 output tiles
        CopyOutTokens(startSeq, curSeqs);
        CopyOutPositions(startSeq, curSeqs);
        CopyOutSeqlens(startSeq, curSeqs);
        CopyOutSlots(startSeq, curSeqs);
    }

private:
    int64_t numSeqs_ = 0;
    int64_t numQueries_ = 0;
    int64_t blockSize_ = 0;
    int64_t maxBlocksPerSeq_ = 0;
    int64_t blockM_ = 0;
    int64_t usedCoreNum_ = 0;
    int64_t tasksPerCore_ = 0;

    AscendC::TPipe pipe_;

    // Global tensors — inputs
    AscendC::GlobalTensor<int64_t> inputTokensGM_;
    AscendC::GlobalTensor<int64_t> sampledGM_;
    AscendC::GlobalTensor<int64_t> inputPositionsGM_;
    AscendC::GlobalTensor<int64_t> seqLensGM_;
    AscendC::GlobalTensor<int64_t> slotMappingGM_;
    AscendC::GlobalTensor<int64_t> blockTablesGM_;

    // Global tensors — outputs
    AscendC::GlobalTensor<int64_t> outTokensGM_;
    AscendC::GlobalTensor<int64_t> outPositionsGM_;
    AscendC::GlobalTensor<int64_t> outSeqlensGM_;
    AscendC::GlobalTensor<int64_t> outSlotsGM_;

    // TQue + TBuf buffers
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> tokensInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> sampledInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> positionsInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> seqlensInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> slotsInQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> btFlatBuf_;

    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> tokensOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> positionsOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> seqlensOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> slotsOutQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> seqlensOldBuf_;

    // Local tensors — input
    AscendC::LocalTensor<int64_t> tokensInLocal_;
    AscendC::LocalTensor<int64_t> sampledInLocal_;
    AscendC::LocalTensor<int64_t> positionsInLocal_;
    AscendC::LocalTensor<int64_t> seqlensInLocal_;
    AscendC::LocalTensor<int64_t> slotsInLocal_;

    // Local tensors — block_tables flat
    AscendC::LocalTensor<int64_t> btFlatLocal_;

    // Local tensors — output
    AscendC::LocalTensor<int64_t> tokensOutLocal_;
    AscendC::LocalTensor<int64_t> positionsOutLocal_;
    AscendC::LocalTensor<int64_t> seqlensOutLocal_;
    AscendC::LocalTensor<int64_t> slotsOutLocal_;

    // Local tensor — seqlens old (scratchpad)
    AscendC::LocalTensor<int64_t> seqlensOldLocal_;
};


extern "C" __global__ __aicore__ void advance_step(
    GM_ADDR in_tokens, GM_ADDR in_sampled,
    GM_ADDR in_positions, GM_ADDR in_seqlens,
    GM_ADDR in_slots, GM_ADDR in_block_tables,
    GM_ADDR out_tokens, GM_ADDR out_positions,
    GM_ADDR out_seqlens, GM_ADDR out_slots,
    int64_t num_seqs, int64_t num_queries,
    int64_t block_size_val, int64_t max_blocks_per_seq,
    int64_t block_m, int64_t used_core_num, int64_t tasks_per_core)
{
    AdvanceStepKernel kernel;
    kernel.Init(
        in_tokens, in_sampled, in_positions, in_seqlens,
        in_slots, in_block_tables,
        out_tokens, out_positions, out_seqlens, out_slots,
        num_seqs, num_queries, block_size_val, max_blocks_per_seq,
        block_m, used_core_num, tasks_per_core);
    kernel.Process();
}
