97	    __aicore__ inline void InitAivBuffers()
98	    {
99	        // TQue for input tiles (BLOCK_M int64 elements each)
100	        pipe_.InitBuffer(tokensInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
101	        pipe_.InitBuffer(sampledInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
102	        pipe_.InitBuffer(positionsInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
103	        pipe_.InitBuffer(seqlensInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
104	        pipe_.InitBuffer(slotsInQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
105	
106	        // TBuf for block_tables flat (max_blocks_per_seq int64 elements)
107	        pipe_.InitBuffer(btFlatBuf_, static_cast<uint32_t>(maxBlocksPerSeq_ * sizeof(int64_t)));
108	
109	        // TQue for output tiles
110	        pipe_.InitBuffer(tokensOutQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
111	        pipe_.InitBuffer(positionsOutQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
112	        pipe_.InitBuffer(seqlensOutQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
113	        pipe_.InitBuffer(slotsOutQueue_, BUFFER_NUM, BLOCK_M * sizeof(int64_t));
114	
115	        // Scalar buffer for seq_lens_old (needed for input_positions and slot_mapping)
116	        pipe_.InitBuffer(seqlensOldBuf_, BLOCK_M * sizeof(int64_t));
117	    }
