119	    __aicore__ inline void Process()
120	    {
121	        if ASCEND_IS_AIV {
122	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
123	
124	            // Preload block_tables[0, :] flat into UB (used for gather by all sequences)
125	            btFlatLocal_ = btFlatBuf_.Get<int64_t>();
126	            LoadGmToUb(btFlatLocal_, blockTablesGM_, static_cast<uint32_t>(maxBlocksPerSeq_));
127	            AscendC::PipeBarrier<PIPE_MTE2>();
128	            AscendC::PipeBarrier<PIPE_ALL>();
129	
130	            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
131	                int bx = coreIdx * tasksPerCore_ + localIdx;
132	                int blockCount = CeilDivI32(static_cast<int32_t>(numSeqs_), BLOCK_M);
133	                if (bx >= blockCount) { continue; }
134	
135	                int startSeq = bx * BLOCK_M;
136	                int curSeqs = static_cast<int32_t>(numSeqs_) - startSeq;
137	                if (curSeqs > BLOCK_M) { curSeqs = BLOCK_M; }
138	
139	                ProcessBlock(startSeq, curSeqs);
140	            }
141	        }
142	    }
