210	    // ── Compute: per-sequence processing ───────────────────────────────
211	    __aicore__ inline void ComputeBlock(int64_t startSeq, int32_t curSeqs)
212	    {
213	        // Allocate output tensors
214	        tokensOutLocal_ = tokensOutQueue_.AllocTensor<int64_t>();
215	        positionsOutLocal_ = positionsOutQueue_.AllocTensor<int64_t>();
216	        seqlensOutLocal_ = seqlensOutQueue_.AllocTensor<int64_t>();
217	        slotsOutLocal_ = slotsOutQueue_.AllocTensor<int64_t>();
218	        seqlensOldLocal_ = seqlensOldBuf_.Get<int64_t>();
219	
220	        // DeQue input tensors after copy-in
221	        tokensInLocal_ = tokensInQueue_.DeQue<int64_t>();
222	        sampledInLocal_ = sampledInQueue_.DeQue<int64_t>();
223	        positionsInLocal_ = positionsInQueue_.DeQue<int64_t>();
224	        seqlensInLocal_ = seqlensInQueue_.DeQue<int64_t>();
225	        slotsInLocal_ = slotsInQueue_.DeQue<int64_t>();
226	
227	        // Save old seq_lens (needed for input_positions and slot_mapping)
228	        for (int i = 0; i < curSeqs; ++i) {
229	            seqlensOldLocal_.SetValue(i, seqlensInLocal_.GetValue(i));
230	        }
231	
232	        // Per-sequence processing
233	        for (int i = 0; i < curSeqs; ++i) {
234	            int64_t seqId = startSeq + i;
235	
236	            if (seqId < numQueries_) {
237	                // Phase A: Valid sequence
238	
239	                // (a) Copy sampled token → input token
240	                int64_t tokenVal = sampledInLocal_.GetValue(i);
241	                tokensOutLocal_.SetValue(i, tokenVal);
242	
243	                // (b) next_seq_len = old_seq_len + 1
244	                int64_t oldSeqLen = seqlensOldLocal_.GetValue(i);
245	                int64_t nextSeqLen = oldSeqLen + 1;
246	                seqlensOutLocal_.SetValue(i, nextSeqLen);
247	
248	                // (c) input_position = old_seq_len (= next_input_pos)
249	                positionsOutLocal_.SetValue(i, oldSeqLen);
250	
251	                // (d) slot_mapping computation
252	                //     next_input_pos = old_seq_len
253	                //     block_index = next_input_pos / block_size
254	                //     block_offset = next_input_pos % block_size
255	                int64_t nextInputPos = oldSeqLen;
256	                int64_t blockIndex = nextInputPos / blockSize_;
257	                int64_t blockOffset = nextInputPos - blockIndex * blockSize_;
258	
259	                // (e) Gather from block_tables_flat[block_index]
260	                int64_t btVal = btFlatLocal_.GetValue(static_cast<int32_t>(blockIndex));
261	
262	                // (f) slot_num = (btVal + max_blocks_per_seq * seqId) * block_size + block_offset
263	                int64_t slotNum = (btVal + maxBlocksPerSeq_ * seqId) * blockSize_ + blockOffset;
264	                slotsOutLocal_.SetValue(i, slotNum);
265	
266	            } else {
267	                // Phase B: Pad sequence — stride-48 reset
268	                // Keep original values by default; only reset every 48th pad element
269	                tokensOutLocal_.SetValue(i, tokensInLocal_.GetValue(i));
270	                positionsOutLocal_.SetValue(i, positionsInLocal_.GetValue(i));
271	                seqlensOutLocal_.SetValue(i, seqlensInLocal_.GetValue(i));
272	
273	                int64_t padIdx = seqId - numQueries_;
274	                // Check: (padIdx // PAD_STRIDE) * PAD_STRIDE == padIdx
275	                int64_t quotient = padIdx / PAD_STRIDE;
276	                int64_t check = quotient * PAD_STRIDE;
277	                if (check == padIdx) {
278	                    tokensOutLocal_.SetValue(i, 0);
279	                    positionsOutLocal_.SetValue(i, 0);
280	                    slotsOutLocal_.SetValue(i, -1);
281	                } else {
282	                    slotsOutLocal_.SetValue(i, slotsInLocal_.GetValue(i));
283	                }
284	            }
285	        }
286	
287	        // Free input tensors
288	        tokensInQueue_.FreeTensor(tokensInLocal_);
289	        sampledInQueue_.FreeTensor(sampledInLocal_);
290	        positionsInQueue_.FreeTensor(positionsInLocal_);
291	        seqlensInQueue_.FreeTensor(seqlensInLocal_);
292	        slotsInQueue_.FreeTensor(slotsInLocal_);
293	
294	        // EnQue output tensors
295	        tokensOutQueue_.EnQue(tokensOutLocal_);
296	        positionsOutQueue_.EnQue(positionsOutLocal_);
297	        seqlensOutQueue_.EnQue(seqlensOutLocal_);
298	        slotsOutQueue_.EnQue(slotsOutLocal_);
299	    }
