301	    // ── ProcessBlock: CopyIn → Compute → CopyOut ────────────────────────
302	    __aicore__ inline void ProcessBlock(int64_t startSeq, int32_t curSeqs)
303	    {
304	        // CopyIn all 5 input tiles
305	        CopyInTokens(startSeq, curSeqs);
306	        CopyInSampled(startSeq, curSeqs);
307	        CopyInPositions(startSeq, curSeqs);
308	        CopyInSeqlens(startSeq, curSeqs);
309	        CopyInSlots(startSeq, curSeqs);
310	
311	        // Compute
312	        ComputeBlock(startSeq, curSeqs);
313	
314	        // CopyOut all 4 output tiles
315	        CopyOutTokens(startSeq, curSeqs);
316	        CopyOutPositions(startSeq, curSeqs);
317	        CopyOutSeqlens(startSeq, curSeqs);
318	        CopyOutSlots(startSeq, curSeqs);
319	    }
