                // (e) Gather from block_tables_flat[block_index]
                int64_t btVal = btFlatLocal_.GetValue(static_cast<int32_t>(blockIndex));

                // (f) slot_num = (btVal + max_blocks_per_seq * seqId) * block_size + block_offset
                int64_t slotNum = (btVal + maxBlocksPerSeq_ * seqId) * blockSize_ + blockOffset;
                slotsOutLocal_.SetValue(i, slotNum);

            } else {
                // Phase B: Pad sequence — stride-48 reset
                // Keep original values by default; only reset every 48th pad element
                tokensOutLocal_.SetValue(i, tokensInLocal_.GetValue(i));
                positionsOutLocal_.SetValue(i, positionsInLocal_.GetValue(i));
                seqlensOutLocal_.SetValue(i, seqlensInLocal_.GetValue(i));

                int64_t padIdx = seqId - numQueries_;
                // Check: (padIdx // PAD_STRIDE) * PAD_STRIDE == padIdx
                int64_t quotient = padIdx / PAD_STRIDE;
                int64_t check = quotient * PAD_STRIDE;
                if (check == padIdx) {
                    tokensOutLocal_.SetValue(i, 0);
                    positionsOutLocal_.SetValue(i, 0);
                    slotsOutLocal_.SetValue(i, -1);
                } else {
                    slotsOutLocal_.SetValue(i, slotsInLocal_.GetValue(i));
                }
            }
