        tokensInQueue_.FreeTensor(tokensInLocal_);
        sampledInQueue_.FreeTensor(sampledInLocal_);
        positionsInQueue_.FreeTensor(positionsInLocal_);
        seqlensInQueue_.FreeTensor(seqlensInLocal_);
        slotsInQueue_.FreeTensor(slotsInLocal_);

        // EnQue output tensors
        tokensOutQueue_.EnQue(tokensOutLocal_);
        positionsOutQueue_.EnQue(positionsOutLocal_);
        seqlensOutQueue_.EnQue(seqlensOutLocal_);
        slotsOutQueue_.EnQue(slotsOutLocal_);
