// AdvanceStep op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>
#include <vector>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_advance_step.h"

namespace ascend_kernel {

constexpr int32_t BLOCK_M = 8;
constexpr int32_t NUM_PHYSICAL_CORES = 20;

std::vector<at::Tensor> advance_step(
    const at::Tensor &input_tokens,
    const at::Tensor &sampled_token_ids,
    const at::Tensor &input_positions,
    const at::Tensor &seq_lens,
    const at::Tensor &slot_mapping,
    const at::Tensor &block_tables,
    int64_t num_seqs,
    int64_t num_queries,
    int64_t block_size)
{
    // Input validation
    TORCH_CHECK(input_tokens.scalar_type() == at::kLong, "input_tokens must be int64");
    TORCH_CHECK(sampled_token_ids.scalar_type() == at::kLong, "sampled_token_ids must be int64");
    TORCH_CHECK(input_positions.scalar_type() == at::kLong, "input_positions must be int64");
    TORCH_CHECK(seq_lens.scalar_type() == at::kLong, "seq_lens must be int64");
    TORCH_CHECK(slot_mapping.scalar_type() == at::kLong, "slot_mapping must be int64");
    TORCH_CHECK(block_tables.scalar_type() == at::kLong, "block_tables must be int64");

    TORCH_CHECK(input_tokens.dim() == 1, "input_tokens must be 1D");
    TORCH_CHECK(sampled_token_ids.dim() == 2, "sampled_token_ids must be 2D");
    TORCH_CHECK(input_positions.dim() == 1, "input_positions must be 1D");
    TORCH_CHECK(seq_lens.dim() == 1, "seq_lens must be 1D");
    TORCH_CHECK(slot_mapping.dim() == 1, "slot_mapping must be 1D");
    TORCH_CHECK(block_tables.dim() == 2, "block_tables must be 2D");

    int64_t max_blocks_per_seq = block_tables.size(1);

    // Create output tensors (clone inputs)
    at::Tensor out_tokens = input_tokens.clone();
    at::Tensor out_positions = input_positions.clone();
    at::Tensor out_seqlens = seq_lens.clone();
    at::Tensor out_slots = slot_mapping.clone();

    // Tiling: core assignment
    int32_t mNum = static_cast<int32_t>((num_seqs + BLOCK_M - 1) / BLOCK_M);
    int32_t usedCoreNum = std::min<int32_t>(NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int64_t block_m_val = static_cast<int64_t>(BLOCK_M);
    int64_t used_core_val = static_cast<int64_t>(usedCoreNum);
    int64_t tasks_per_core_val = static_cast<int64_t>(tasksPerCore);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(advance_step, blockDim,
                    out_tokens, sampled_token_ids, out_positions, out_seqlens,
                    out_slots, block_tables,
                    out_tokens, out_positions, out_seqlens, out_slots,
                    num_seqs, num_queries, block_size, max_blocks_per_seq,
                    block_m_val, used_core_val, tasks_per_core_val);

    return {out_tokens, out_positions, out_seqlens, out_slots};
}

}  // namespace ascend_kernel
